// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint128).max);
        Reverter target = new Reverter();
        vm.deal(address(c), amount);
        vm.prank(c.owner());
        bool ok = true;
        try c.sendMoney(address(target), amount, abi.encode()) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "sendMoney must ignore a failing callee");
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
